import { ShadowConfig, ShadowParams, TiledBoolProp } from "type";
import { GameScene } from "../GameScene";
import { calculateAngle, fastFloor, formatProperties } from "utils";
import { Raycaster } from ".";

export class Shadow {
  constructor(ray: Raycaster, config: ShadowConfig) {
    this.config = config;
    this.scene = ray.scene;
    this.ray = ray;
    const props = formatProperties<"fromCenter" | "move">(config.properties);

    const fromCenter = props.fromCenter as TiledBoolProp | undefined;
    const move = props.move as TiledBoolProp | undefined;

    if (fromCenter?.value || move?.value)
      this.params.type = fromCenter ? "fromCenter" : "move";

    const sunShadow = this.createShadow();

    this.sprites = {
      sun: sunShadow,
      lights: [],
    };
  }
  private scene: GameScene;
  private config: ShadowConfig;
  private ray?: Raycaster;

  private params: ShadowParams = {
    type: "default",
  };
  private sprites: {
    sun: Phaser.GameObjects.Sprite;
    lights: Phaser.GameObjects.Sprite[];
  };

  private createShadow = () => {
    const { type } = this.params;
    const { height, width, x, y, id } = this.config;

    const shadowWidth = width;
    const shadowHeight = height;

    const sprite = this.scene.add.sprite(
      x + width / 2,
      y + shadowHeight - shadowWidth / 2,
      "shadow_texture",
    );
    sprite.setScale(shadowWidth / sprite.width, shadowHeight / sprite.height);
    // sprite.setDepth(Infinity);
    switch (type) {
      case "default":
        sprite.setOrigin(0.5, 1);
        break;
      case "fromCenter":
        sprite.setOrigin(0.5);
        break;
      case "move":
        // sprite.setOrigin(0.5);
        break;

      default:
        break;
    }

    this.ray?.shadowContainer.add(sprite);

    return sprite;
  };

  private rotateSunShadow = () => {
    const { type } = this.params;
    const { sun } = this.scene;
    const { sun: sunSprite } = this.sprites;

    const { x = 0, y = 0 } = sun?.sunPosition || {};
    const { x: sX, y: sY } = sunSprite;

    switch (type) {
      case "default":
      case "fromCenter":
        const angle = calculateAngle(x, y, sX, sY);
        sunSprite.setAngle(angle + 90);
        break;

      default:
        break;
    }
  };

  update = () => {
    this.rotateSunShadow();
  };
}
